export type Locale = 'ar' | 'en';

export const dictionaries = {
  ar: { products: 'المنتجات', about: 'من نحن', brands: 'العلامات التجارية', contact: 'تواصل معنا' },
  en: { products: 'Products', about: 'About', brands: 'Brands', contact: 'Contact' },
} as const;

export function getDictionary(locale: Locale = 'ar') {
  return dictionaries[locale];
}
